export const getSetSeriesUrl = (clubId: number,) => {




  return `/api/admin/clubs/${clubId}/series`
}

/**
 * Sets the series in which the club participates.
 *
 * The year is embedded in the series: an assignment to "DSBL 2026" does not apply to
 * "DSBL 2027" — a new assignment is needed there. An assignment under which racing has
 * already occurred cannot be removed; results depend on it.
 * @summary Assign series
 */
export const setSeries = async (clubId: number,
    seriesAssignment: SeriesAssignment, options?: RequestInit): Promise<ClubAdminOut> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return http<ClubAdminOut>(getSetSeriesUrl(clubId),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(seriesAssignment)
  }
);}





