export const getTestEmailUrl = () => {




  return `/api/dev/test-email`
}

/**
 * Sends a real message with a throwaway code to the given address right now, and
 * reports the outcome directly in the response — the same send path
 * `app.services.login.request_email_code` uses (SMTP or Brevo, whichever
 * `app.mail.send_login_code` picks), just without needing a valid account or the
 * anti-enumeration silence that endpoint deliberately has.
 * @summary Attempt an actual send
 */
export const testEmail = async (testEmailBody: TestEmail, options?: RequestInit): Promise<TestEmailOut> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return http<TestEmailOut>(getTestEmailUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(testEmailBody)
  }
);}





export const getTestEmailMutationKey = () => ['testEmail'] as const;

export const getTestEmailMutationOptions = <TError = ErrorType<HTTPValidationError>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof testEmail>>, TError,TestEmailMutationVariables, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof testEmail>>, TError,TestEmailMutationVariables, TContext> => {

const mutationKey = getTestEmailMutationKey();
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof testEmail>>, TestEmailMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  testEmail(data,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type TestEmailMutationResult = NonNullable<Awaited<ReturnType<typeof testEmail>>>
    export type TestEmailMutationBody = BodyType<TestEmail>
    export type TestEmailMutationError = ErrorType<HTTPValidationError>
    export type TestEmailMutationVariables = {data: BodyType<TestEmail>}

    /**
 * @summary Attempt an actual send
 */
export const useTestEmail = <TError = ErrorType<HTTPValidationError>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof testEmail>>, TError,TestEmailMutationVariables, TContext>, }
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof testEmail>>,
        TError,
        TestEmailMutationVariables,
        TContext
      > => {
      return useMutation(getTestEmailMutationOptions(options), queryClient);
    }

export const getNetworkProbeUrl = (params?: NetworkProbeParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/dev/network-probe?${stringifiedParams}` : `/api/dev/network-probe`
}

/**
 * Resolves `host` (default: the configured SMTP host) and tries a raw TCP connect to
 * *each* resolved address individually — this tells apart a common container gotcha
 * (DNS returns an address family, usually IPv6, with no actual outbound route, while the
 * other family would work fine) from every address genuinely being blocked (e.g. the
 * platform firewalling the port itself).
 * @summary Diagnose outbound TCP
 */
export const networkProbe = async (params?: NetworkProbeParams, options?: RequestInit): Promise<NetworkProbeOut> => {

  return http<NetworkProbeOut>(getNetworkProbeUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getNetworkProbeQueryKey = (params?: NetworkProbeParams,) => {
    return [
    `/api/dev/network-probe`, ...(params ? [params] : [])
    ] as const;
    }


